/* RH Engefex — registros sincronizados pelo estado compartilhado do Gerenciador. */
(function(root){'use strict';
const h=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;'}[c]));
const types=['ASO','NR-35','PTA','MUNK','SOLDA','EPI / NR-06','NR-18','NR-12','USO DE IMAGEM'];
const days=[30,15,7,0];
let category='todos',status='todos',query='',employment='ativos';
const isActive=e=>e.active!==false&&e.employmentStatus!=='inativo';
const startOfDay=()=>{let d=new Date();return new Date(d.getFullYear(),d.getMonth(),d.getDate()).getTime()};
function offset(date){if(!/^\d{4}-\d{2}-\d{2}$/.test(date||''))return null;const [y,m,d]=date.split('-').map(Number);return Math.round((new Date(y,m-1,d).getTime()-startOfDay())/86400000)}
function phase(date){let diff=offset(date);return diff===null?'Não informado':diff<0?'Vencido':diff<=30?'A vencer':'Em dia'}
const badge=(date)=>{const p=phase(date);return '<span class="tag">'+h(p)+(offset(date)!==null?' · '+offset(date)+' dias':'')+'</span>'};
const model=s=>({employees:s.hrEmployees||[],docs:s.hrDocuments||[],settings:s.hrSettings||{recipients:[],days}});
function issues(s){const m=model(s);return m.docs.filter(d=>d.due&&offset(d.due)<=30&&m.employees.some(e=>e.id===d.employeeId&&isActive(e))).map(d=>({doc:d,employee:m.employees.find(e=>e.id===d.employeeId),remaining:offset(d.due)})).sort((a,b)=>a.remaining-b.remaining)}
function page(s){const m=model(s),a=m.employees.filter(e=>(employment==='ativos'?isActive(e):!isActive(e))&&(category==='todos'||e.category===category)&&(!query||e.name.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))));let ds=m.docs.filter(d=>a.some(e=>e.id===d.employeeId)&& (status==='todos'||phase(d.due)===status));const pending=employment==='ativos'?issues(s).filter(x=>category==='todos'||x.employee.category===category):[];
return '<section class="page-head"><div><h1>Recursos Humanos</h1><p>Controle de documentos, vencimentos e pendências.</p></div></section>'+
'<section class="panel"><div class="panel-head"><h2>Funcionários e documentos</h2></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px"><button type="button" class="button '+(employment==='ativos'?'primary':'secondary')+'" data-hr-employment="ativos">Ativos ('+m.employees.filter(isActive).length+')</button><button type="button" class="button '+(employment==='inativos'?'primary':'secondary')+'" data-hr-employment="inativos">Inativos ('+m.employees.filter(e=>!isActive(e)).length+')</button></div><div class="form-grid">'+
'<label>Categoria<select id="hrCategory"><option value="todos">Todos</option><option value="pedreiros" '+(category==='pedreiros'?'selected':'')+'>Pedreiros</option><option value="outros" '+(category==='outros'?'selected':'')+'>Demais funcionários</option></select></label>'+
'<label>Situação<select id="hrStatus">'+['todos','Vencido','A vencer','Em dia','Não informado'].map(v=>'<option '+(status===v?'selected':'')+' value="'+v+'">'+v+'</option>').join('')+'</select></label>'+
'<label>Buscar funcionário<input id="hrQuery" value="'+h(query)+'" placeholder="Nome"></label></div>'+
'<p><button class="button primary" id="hrNew">+ Funcionário</button> <button class="button secondary" id="hrExport">Exportar JSON</button> <label class="button secondary" style="cursor:pointer">Importar JSON<input type="file" id="hrImport" accept=".json,application/json" hidden></label></p></section>'+
'<section class="panel"><div class="panel-head"><h2>Funcionários '+(employment==='ativos'?'ativos':'inativos')+' ('+a.length+')</h2></div><div style="overflow:auto"><table><thead><tr><th>Nome</th><th>Categoria</th><th>Situação</th><th>Ação</th></tr></thead><tbody>'+a.map(e=>'<tr><td>'+h(e.name)+'</td><td>'+h(e.category)+'</td><td>'+(isActive(e)?'Ativo':'Inativo')+'</td><td><button type="button" class="button secondary" data-hr-toggle="'+h(e.id)+'">'+(isActive(e)?'Inativar':'Reativar')+'</button></td></tr>').join('')+'</tbody></table></div></section>'+ 
'<section class="panel"><div class="panel-head"><h2>Pendências RH ('+pending.length+')</h2></div>'+
(pending.length?'<div style="overflow:auto"><table><thead><tr><th>Funcionário</th><th>Categoria</th><th>Documento</th><th>Vencimento</th><th>Situação</th></tr></thead><tbody>'+
pending.map(x=>'<tr><td>'+h(x.employee.name)+'</td><td>'+h(x.employee.category)+'</td><td>'+h(x.doc.type)+'</td><td>'+h(x.doc.due)+'</td><td>'+badge(x.doc.due)+'</td></tr>').join('')+'</tbody></table></div>':'<p>Nenhuma pendência dentro de 30 dias.</p>')+'</section>'+
'<section class="panel"><div class="panel-head"><h2>Documentos ('+ds.length+')</h2></div><div style="overflow:auto"><table><thead><tr><th>Funcionário</th><th>Documento</th><th>Emissão</th><th>Vencimento</th><th>Situação</th><th></th></tr></thead><tbody>'+
ds.map(d=>'<tr><td>'+h(m.employees.find(e=>e.id===d.employeeId)?.name||'')+'</td><td>'+h(d.type)+'</td><td>'+h(d.issued||'—')+'</td><td>'+h(d.due||'—')+'</td><td>'+badge(d.due)+'</td><td><button class="button secondary" data-hr-edit="'+h(d.id)+'">Renovar / editar</button></td></tr>').join('')+'</tbody></table></div></section>'+
'<section class="panel"><div class="panel-head"><h2>Cadastro de documentos</h2></div><form id="hrDocForm" class="form-grid"><label>Funcionário<select name="employeeId" required>'+m.employees.filter(isActive).map(e=>'<option value="'+h(e.id)+'">'+h(e.name)+'</option>').join('')+'</select></label><label>Tipo<select name="type">'+types.map(t=>'<option>'+h(t)+'</option>').join('')+'</select></label><label>Emissão<input type="date" name="issued"></label><label>Validade em meses<input name="months" type="number" min="1" max="120" placeholder="Opcional"></label><label>Vencimento<input type="date" name="due" required></label><button class="button primary" type="submit">Salvar documento</button></form></section>'+
'<section class="panel"><div class="panel-head"><h2>Responsáveis por alertas</h2></div><p>Notificações internas: 30, 15 e 7 dias antes e no vencimento. E-mails desativados. Para receber alertas é necessário informar o e-mail do usuário cadastrado, respeitando as permissões do módulo.</p><form id="hrRecipientForm"><label>E-mails dos destinatários (separados por vírgula)<input name="recipients" type="text" value="'+h((m.settings.recipients||[]).join(', '))+'" placeholder="rh@empresa.com"></label><button class="button primary" type="submit">Salvar destinatários</button></form></section>';
}
function attach(s,persist,render,notify){
 document.querySelectorAll('[data-hr-employment]').forEach(b=>b.onclick=()=>{employment=b.dataset.hrEmployment;render()});
 document.querySelectorAll('[data-hr-toggle]').forEach(b=>b.onclick=async()=>{if(!root.EngefexAccess?.canWrite('hr'))return notify('Sem permissão para editar RH.');const current=(s.hrEmployees||[]).find(e=>e.id===b.dataset.hrToggle);if(!current)return;const activate=!isActive(current);if(!confirm(activate?'Reativar '+current.name+'?':'Inativar '+current.name+'? O histórico será preservado e os alertas deixarão de ser exibidos.'))return;const n=structuredClone(s);const e=n.hrEmployees.find(x=>x.id===current.id);e.active=activate;e.employmentStatus=activate?'ativo':'inativo';e.employmentChangedAt=new Date().toISOString();await persist(n,activate?'Funcionário reativado.':'Funcionário inativado.');render()});
 const change=()=>{category=document.getElementById('hrCategory')?.value||'todos';status=document.getElementById('hrStatus')?.value||'todos';query=document.getElementById('hrQuery')?.value||'';render()};
 ['hrCategory','hrStatus'].forEach(id=>{let e=document.getElementById(id);if(e)e.onchange=change});
 const q=document.getElementById('hrQuery');if(q)q.onchange=change;
 const edit=async d=>{if(!root.EngefexAccess?.canWrite('hr'))return notify('Acesso somente de leitura.');const issued=prompt('Data de emissão (AAAA-MM-DD):',d.issued||'');if(issued===null)return;const due=prompt('Nova data de vencimento (AAAA-MM-DD):',d.due||'');if(due===null)return;if(!/^\d{4}-\d{2}-\d{2}$/.test(due))return notify('Informe a data AAAA-MM-DD.');let next=structuredClone(s);let doc=next.hrDocuments.find(x=>x.id===d.id);doc.history=[...(doc.history||[]),{issued:doc.issued,due:doc.due,recordedAt:new Date().toISOString()}];doc.issued=issued;doc.due=due;await persist(next,'Documento de RH atualizado.');render()};
 document.querySelectorAll('[data-hr-edit]').forEach(b=>b.onclick=()=>edit((s.hrDocuments||[]).find(d=>d.id===b.dataset.hrEdit)));
 const newBtn=document.getElementById('hrNew');if(newBtn)newBtn.onclick=async()=>{if(!root.EngefexAccess?.canWrite('hr'))return notify('Sem permissão.');let name=prompt('Nome completo do funcionário:');if(!name?.trim())return;let cat=confirm('O funcionário é pedreiro?')?'pedreiros':'outros';let n=structuredClone(s);n.hrEmployees=[...(n.hrEmployees||[]),{id:crypto.randomUUID(),name:name.trim(),category:cat,active:true,employmentStatus:'ativo'}];await persist(n,'Funcionário cadastrado.');render()};
 const form=document.getElementById('hrDocForm');if(form)form.onsubmit=async ev=>{ev.preventDefault();if(!root.EngefexAccess?.canWrite('hr'))return notify('Sem permissão.');let f=new FormData(form),issued=f.get('issued'),due=f.get('due'),months=Number(f.get('months'));if(issued&&months){let d=new Date(issued+'T12:00:00');d.setMonth(d.getMonth()+months);due=d.toISOString().slice(0,10)}if(!due)return notify('Informe um vencimento ou emissão e prazo.');let n=structuredClone(s);n.hrDocuments=[...(n.hrDocuments||[]),{id:crypto.randomUUID(),employeeId:f.get('employeeId'),type:f.get('type'),issued,due,history:[]}];await persist(n,'Documento registrado.');render()};
 const rec=document.getElementById('hrRecipientForm');if(rec)rec.onsubmit=async ev=>{ev.preventDefault();if(!root.EngefexAccess?.isAdmin)return notify('Somente administradores alteram destinatários.');let n=structuredClone(s);n.hrSettings={days,recipients:String(new FormData(rec).get('recipients')||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean),email:false};await persist(n,'Destinatários salvos.');render()};
 const exp=document.getElementById('hrExport');if(exp)exp.onclick=()=>{const data=JSON.stringify(model(s),null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='engefex-rh.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
 const imp=document.getElementById('hrImport');if(imp)imp.onchange=async()=>{if(!root.EngefexAccess?.canWrite('hr'))return notify('Sem permissão.');try{const v=JSON.parse(await imp.files[0].text());if(!Array.isArray(v.employees)||!Array.isArray(v.docs))throw Error('Arquivo incompatível');const n=structuredClone(s);n.hrEmployees=[...(n.hrEmployees||[]),...v.employees.filter(e=>!n.hrEmployees?.some(x=>x.id===e.id)).map(e=>({...e,active:e.active!==false&&e.employmentStatus!=='inativo',employmentStatus:e.active===false||e.employmentStatus==='inativo'?'inativo':'ativo'}))];n.hrDocuments=[...(n.hrDocuments||[]),...v.docs.filter(d=>!n.hrDocuments?.some(x=>x.id===d.id))];await persist(n,'Dados de RH importados.');render()}catch(e){notify(e.message)}};
}
function myAlerts(s,email){let m=model(s);if(!(m.settings.recipients||[]).includes(String(email||'').toLowerCase()))return [];if(!root.EngefexAccess?.canRead('hr'))return [];return issues(s).filter(x=>days.includes(x.remaining)).map(x=>({id:'rh-'+x.doc.id+'-'+x.doc.due+'-'+x.remaining,title:'RH: '+x.employee.name+' — '+x.doc.type,detail:x.remaining===0?'Vence hoje':'Vence em '+x.remaining+' dias',href:'#hr'}))}
function myPending(s,email){let m=model(s);if(!(m.settings.recipients||[]).includes(String(email||'').toLowerCase())||!root.EngefexAccess?.canRead('hr'))return [];return issues(s).map(x=>({id:'rh-'+x.doc.id,title:'RH: '+x.employee.name+' — '+x.doc.type,detail:x.remaining<0?'Vencido há '+(-x.remaining)+' dias':x.remaining===0?'Vence hoje':'Vence em '+x.remaining+' dias'}))}
root.EngefexRH={page,attach,issues,myAlerts,myPending};
})(window);
